var SORTS = {
  "importedAt-desc": "f.imported_at DESC, f.id DESC",
  "importedAt-asc": "f.imported_at ASC, f.id ASC",
  "fileName-asc": "f.stored_file_name COLLATE NOCASE ASC, f.id ASC",
  "createdAt-desc": "f.created_at_file IS NULL, f.created_at_file DESC, f.id DESC"
};
var SEARCH_COLUMNS = [
  "f.source_file_name",
  "f.stored_file_name",
  "f.device_file_name",
  "f.specimen_id",
  "s.display_name",
  "f.state_tag",
  "f.memo",
  "f.tags_json",
  "f.plan_id",
  "p.name"
];
function listFiles(db, query = {}) {
  const where = [];
  const params = {};
  if (query.planId !== void 0) {
    where.push("f.plan_id = $plan");
    params.plan = query.planId;
  }
  if (query.specimenId !== void 0) {
    where.push("f.specimen_id = $specimen COLLATE NOCASE");
    params.specimen = nfc(query.specimenId).trim();
  }
  if (query.stateTag !== void 0) {
    where.push("f.state_tag = $stateTag");
    params.stateTag = nfc(query.stateTag).trim();
  }
  const terms = nfc(query.text ?? "").split(/\s+/).filter((t) => t.length > 0).slice(0, 10);
  terms.forEach((t, i) => {
    where.push(`(${SEARCH_COLUMNS.map((c) => `${c} LIKE $t${i} ESCAPE '\\'`).join(" OR ")})`);
    params[`t${i}`] = likePattern(t);
  });
  const offset = Math.max(0, Math.trunc(query.offset ?? 0));
  const limit = Math.min(MAX_FILE_LIMIT, Math.max(1, Math.trunc(query.limit ?? DEFAULT_FILE_LIMIT)));
  const from = `FROM files f JOIN plans p ON p.id = f.plan_id JOIN specimens s ON s.id = f.specimen_id
    ${where.length ? `WHERE ${where.join(" AND ")}` : ""}`;
  const total = num2(db.get(`SELECT count(*) AS n ${from}`, params)?.n);
  const order = SORTS[query.sort ?? "importedAt-desc"] ?? SORTS["importedAt-desc"];
  const rows = db.all(`SELECT f.* ${from} ORDER BY ${order} LIMIT $limit OFFSET $offset`, { ...params, limit, offset });
  return { items: rows.map(toFile), total, offset, limit };
}

// src/core/catalog/imports.ts
var STATUSES = ["completed", "partial", "failed", "cancelled"];
var count = (v) => Number.isSafeInteger(v) && v >= 0 ? v : 0;
function beginImportBatch(db, input) {
  db.run(
    `INSERT INTO import_batches(id, started_at, input_paths_json, total_items)
     VALUES ($id, $at, $paths, $total)`,
    {
      id: requireText(input.batchId, "\uBC30\uCE58 ID"),
      at: requireText(input.startedAt, "\uC2DC\uC791 \uC2DC\uAC01"),
      paths: JSON.stringify(input.inputPaths ?? []),
      total: count(input.totalItems)
    }
  );
}
function finishImportBatch(db, input) {
  if (!STATUSES.includes(input.status)) throw new AppError("INVALID_ARGUMENT", "\uAC00\uC838\uC624\uAE30 \uC0C1\uD0DC \uAC12\uC774 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.");
  const r = db.run(
    `UPDATE import_batches SET finished_at = $at, status = $status, copied_count = $copied, skipped_count = $skipped,
       failed_count = $failed, created_plan_ids_json = $plans, total_bytes = $bytes
     WHERE id = $id`,
    {
      id: input.batchId,
      at: requireText(input.finishedAt, "\uC885\uB8CC \uC2DC\uAC01"),
      status: input.status,
      copied: count(input.copiedCount),
      skipped: count(input.skippedCount),
      failed: count(input.failedCount),
      plans: JSON.stringify(input.createdPlanIds ?? []),
      bytes: count(input.totalBytes)
    }
  );
  if (r.changes === 0) throw new AppError("NOT_FOUND", `\uAC00\uC838\uC624\uAE30 \uBC30\uCE58 ${input.batchId} \uC744(\uB97C) \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.`);
}
function recordImportItem(db, batchId, item) {
  db.run(
    `INSERT OR REPLACE INTO import_items(batch_id, item_id, source_path, file_name, outcome, message, file_id, plan_id,
       specimen_id, stored_rel_path)
     VALUES ($batch, $item, $src, $name, $outcome, $msg, $file, $plan, $specimen, $rel)`,
    {
      batch: batchId,
      item: item.itemId,
      src: item.sourcePath,
      name: item.fileName,
      outcome: item.status,
      msg: item.errorMessage,
      file: item.fileId,
      plan: item.planId,
      specimen: item.specimenId,
      rel: item.storedRelPath
    }
  );
}
function listImportItems(db, batchId) {
  return db.all("SELECT * FROM import_items WHERE batch_id = $b ORDER BY item_id", { b: batchId }).map((r) => ({
    itemId: str2(r.item_id),
    sourcePath: str2(r.source_path),
    fileName: str2(r.file_name),
    status: str2(r.outcome),
    fileId: numOrNull(r.file_id),
    planId: strOrNull(r.plan_id),
    specimenId: strOrNull(r.specimen_id),
    storedRelPath: strOrNull(r.stored_rel_path),
    errorMessage: strOrNull(r.message)
  }));
}
function toHistory(r) {
  return {
    batchId: str2(r.id),
    startedAt: str2(r.started_at),
    finishedAt: strOrNull(r.finished_at),
    status: strOrNull(r.status) ?? "interrupted",
    inputPaths: parseJson(r.input_paths_json, []),
    totalItems: num2(r.total_items),
    copiedCount: num2(r.copied_count),
    skippedCount: num2(r.skipped_count),
    failedCount: num2(r.failed_count),
    createdPlanIds: parseJson(r.created_plan_ids_json, []),
    totalBytes: num2(r.total_bytes)
  };
}
function listImportHistory(db) {
  return db.all("SELECT * FROM import_batches ORDER BY started_at DESC, rowid DESC").map(toHistory);
}

