function intervalGap(aStart, aEnd, bStart, bEnd) {
  const o = Math.min(aEnd, bEnd) - Math.max(aStart, bStart);
  return { overlapMm: Math.max(0, o), gapMm: Math.max(0, -o) };
}
function mergeSpans(spans) {
  const sorted = spans.filter((s) => s.endMm > s.startMm).map((s) => ({ frameKey: s.frameKey, startMm: s.startMm, endMm: s.endMm })).sort((x, y) => x.frameKey < y.frameKey ? -1 : x.frameKey > y.frameKey ? 1 : x.startMm - y.startMm);
  const out2 = [];
  for (const s of sorted) {
    const last = out2[out2.length - 1];
    if (last && last.frameKey === s.frameKey && s.startMm <= last.endMm) last.endMm = Math.max(last.endMm, s.endMm);
    else out2.push(s);
  }
  return out2;
}
function intersectCoverage(a, b2) {
  const ma = mergeSpans(a);
  const mb2 = mergeSpans(b2);
  const out2 = [];
  for (const x of ma) {
    for (const y of mb2) {
      if (x.frameKey !== y.frameKey) continue;
      const s = Math.max(x.startMm, y.startMm);
      const e = Math.min(x.endMm, y.endMm);
      if (e > s) out2.push({ frameKey: x.frameKey, startMm: s, endMm: e });
    }
  }
  return mergeSpans(out2);
}
function touchesCoverage(frameKey, startMm, endMm, coverage) {
  for (const c of coverage) {
    if (c.frameKey !== frameKey) continue;
    if (endMm === startMm) {
      if (startMm >= c.startMm && startMm <= c.endMm) return true;
    } else if (startMm < c.endMm && endMm > c.startMm) return true;
  }
  return false;
}

