  const current = currentSchemaVersion(db);
  if (current < 1 || pendingMigrations(db).length === 0) return null;
  const base2 = basename(dbPath).replace(/\.db$/i, "");
  let target = join(dirname(dbPath), `${base2}.v${current}-${backupStamp(nowIso)}.bak`);
  for (let n = 2; existsSync(target); n++) target = join(dirname(dbPath), `${base2}.v${current}-${backupStamp(nowIso)}-${n}.bak`);
